import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { persistentBrowser } from '../src/utils/persistentBrowser.js';

describe('Persistent Browser (RobotkezV2 - Phase 1)', () => {
    // Timeout for browser operations
    const BROWSER_TIMEOUT = 15000;

    beforeAll(async () => {
        // Launch browser once for all tests
        await persistentBrowser.sendCommand({ action: 'launch', headless: true });
    }, BROWSER_TIMEOUT);

    afterAll(async () => {
        // Close browser after all tests
        await persistentBrowser.close();
    });

    it('should navigate to a URL', async () => {
        const res = await persistentBrowser.sendCommand({
            action: 'navigate',
            url: 'https://example.com'
        });

        expect(res.status).toBe('success');
        expect(res.url).toContain('example.com');
    }, BROWSER_TIMEOUT);

    it('should scroll page down', async () => {
        await persistentBrowser.sendCommand({
            action: 'navigate',
            url: 'https://example.com'
        });

        const res = await persistentBrowser.sendCommand({
            action: 'scroll',
            direction: 'down',
            amount: 200
        });

        expect(res.status).toBe('success');
        expect(res.message).toContain('Scrolled down');
    }, BROWSER_TIMEOUT);

    it('should wait for element to appear', async () => {
        await persistentBrowser.sendCommand({
            action: 'navigate',
            url: 'https://example.com'
        });

        const res = await persistentBrowser.sendCommand({
            action: 'wait',
            selector: 'h1',
            timeout: 5000
        });

        expect(res.status).toBe('success');
        expect(res.message).toContain('is visible');
    }, BROWSER_TIMEOUT);

    it('should extract text from elements', async () => {
        await persistentBrowser.sendCommand({
            action: 'navigate',
            url: 'https://example.com'
        });

        const res = await persistentBrowser.sendCommand({
            action: 'extract',
            selector: 'h1',
            type: 'text'
        });

        expect(res.status).toBe('success');
        expect(res.data).toBeInstanceOf(Array);
        expect(res.count).toBeGreaterThan(0);
    }, BROWSER_TIMEOUT);

    it('should take a screenshot', async () => {
        await persistentBrowser.sendCommand({
            action: 'navigate',
            url: 'https://example.com'
        });

        const res = await persistentBrowser.sendCommand({
            action: 'screenshot'
        });

        expect(res.status).toBe('success');

        // Verify screenshot was saved
        const screenshot = persistentBrowser.getLastScreenshot();
        expect(screenshot).not.toBeNull();
        expect(screenshot).toBeInstanceOf(Uint8Array);
    }, BROWSER_TIMEOUT);

    it('should get HTML content', async () => {
        await persistentBrowser.sendCommand({
            action: 'navigate',
            url: 'https://example.com'
        });

        const res = await persistentBrowser.sendCommand({
            action: 'content'
        });

        expect(res.status).toBe('success');
        expect(res.content).toBeDefined();
        expect(res.content).toContain('<html');
    }, BROWSER_TIMEOUT);

    it('should handle scroll with different directions', async () => {
        await persistentBrowser.sendCommand({
            action: 'navigate',
            url: 'https://example.com'
        });

        const directions: Array<'up' | 'down' | 'left' | 'right'> = ['down', 'up', 'left', 'right'];

        for (const direction of directions) {
            const res = await persistentBrowser.sendCommand({
                action: 'scroll',
                direction,
                amount: 50
            });

            expect(res.status).toBe('success');
            expect(res.message).toContain(`Scrolled ${direction}`);
        }
    }, BROWSER_TIMEOUT);

    it('should handle timeout on wait for non-existent element', async () => {
        await persistentBrowser.sendCommand({
            action: 'navigate',
            url: 'https://example.com'
        });

        try {
            await persistentBrowser.sendCommand({
                action: 'wait',
                selector: '#non-existent-element-12345',
                timeout: 2000
            });
            expect.fail('Should have thrown timeout error');
        } catch (error: any) {
            expect(error.message).toContain('Timeout');
        }
    }, BROWSER_TIMEOUT);

    it('should extract attributes from elements', async () => {
        await persistentBrowser.sendCommand({
            action: 'navigate',
            url: 'https://example.com'
        });

        const res = await persistentBrowser.sendCommand({
            action: 'extract',
            selector: 'a',
            type: 'attribute',
            attribute: 'href'
        });

        expect(res.status).toBe('success');
        expect(res.data).toBeInstanceOf(Array);
        // example.com might not have links, so count could be 0
        expect(res.count).toBeGreaterThanOrEqual(0);
    }, BROWSER_TIMEOUT);
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import express from "express";
import request from "supertest";
import fs from "fs/promises";
import os from "os";
import path from "path";
import { suggestedTasksRouter } from "../src/server/routes/suggestedTasks.js";
import { initSuggestedTasksDb, getSuggestedTasksDb } from "../src/core/suggestedTasksScanner.js";

interface TaskRecord {
  id: string;
  todo_text: string;
  file_path: string;
  line_number: number;
  confidence_score: number;
  status: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function getString(value: unknown, key: string): string | undefined {
  if (!isRecord(value)) return undefined;
  const entry = value[key];
  return typeof entry === "string" ? entry : undefined;
}

function getNumber(value: unknown, key: string): number | undefined {
  if (!isRecord(value)) return undefined;
  const entry = value[key];
  return typeof entry === "number" ? entry : undefined;
}

function getArray(value: unknown, key: string): unknown[] {
  if (!isRecord(value)) return [];
  const entry = value[key];
  return Array.isArray(entry) ? entry : [];
}

async function seedWorkspace(root: string) {
  const srcDir = path.join(root, "src");
  await fs.mkdir(srcDir, { recursive: true });
  await fs.writeFile(
    path.join(srcDir, "sample.ts"),
    "// TODO CRITICAL: fix this\nconst sample = true;\n",
    "utf-8",
  );
}

function insertTask(status = "pending"): TaskRecord {
  const db = getSuggestedTasksDb();
  if (!db) throw new Error("Suggested tasks DB not initialized");

  const id = `todo_test_${status}`;
  db.prepare(
    `
      INSERT OR REPLACE INTO suggested_tasks
      (id, file_path, line_number, todo_text, context, confidence_score, status, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
    `,
  ).run(id, "src/sample.ts", 1, "TODO: test", "context", 0.7, status);

  return {
    id,
    todo_text: "TODO: test",
    file_path: "src/sample.ts",
    line_number: 1,
    confidence_score: 0.7,
    status,
  };
}

describe("SuggestedTasksScanner API Routes", () => {
  let app: express.Express;
  let tempDir: string;
  const prevEnv = { ...process.env };

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "suggested-tasks-"));
    await seedWorkspace(tempDir);
    process.env.BRUNELLA_WORKSPACE_ROOT = tempDir;

    await initSuggestedTasksDb(":memory:");

    app = express();
    app.use(express.json());
    app.use("/api/v1/suggested-tasks", suggestedTasksRouter);
  });

  afterEach(async () => {
    process.env = { ...prevEnv };
    await fs.rm(tempDir, { recursive: true, force: true });
  });

  describe("GET /api/v1/suggested-tasks", () => {
    it("should return all non-archived tasks", async () => {
      insertTask("pending");
      const response = await request(app).get("/api/v1/suggested-tasks");

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
      expect(Array.isArray(response.body.data)).toBe(true);
    });
  });

  describe("GET /api/v1/suggested-tasks/:status", () => {
    it("should filter tasks by pending status", async () => {
      insertTask("pending");
      insertTask("in_progress");

      const response = await request(app).get("/api/v1/suggested-tasks/pending");

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
      const tasks = Array.isArray(response.body.data) ? response.body.data : [];
      tasks.forEach((task: unknown) => {
        expect(getString(task, "status")).toBe("pending");
      });
    });

    it("should filter tasks by in_progress status", async () => {
      insertTask("in_progress");
      const response = await request(app).get("/api/v1/suggested-tasks/in_progress");

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
    });

    it("should return 400 for invalid status", async () => {
      const response = await request(app).get("/api/v1/suggested-tasks/invalid_status");
      expect(response.status).toBe(400);
    });
  });

  describe("POST /api/v1/suggested-tasks/scan", () => {
    it("should scan codebase and return new tasks", async () => {
      const response = await request(app).post("/api/v1/suggested-tasks/scan");

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
      const count = getNumber(response.body.data, "count");
      expect(typeof count).toBe("number");
    });
  });

  describe("PATCH /api/v1/suggested-tasks/:taskId/status", () => {
    it("should update task status successfully", async () => {
      const task = insertTask("pending");

      const response = await request(app)
        .patch(`/api/v1/suggested-tasks/${task.id}/status`)
        .send({ status: "in_progress" });

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
      expect(getString(response.body.data, "status")).toBe("in_progress");
    });

    it("should return 400 for invalid status value", async () => {
      const response = await request(app)
        .patch("/api/v1/suggested-tasks/test-id/status")
        .send({ status: "invalid" });

      expect(response.status).toBe(400);
    });

    it("should return 404 for non-existent task", async () => {
      const response = await request(app)
        .patch("/api/v1/suggested-tasks/nonexistent-id/status")
        .send({ status: "completed" });

      expect(response.status).toBe(404);
    });
  });

  describe("DELETE /api/v1/suggested-tasks/:taskId", () => {
    it("should archive a task successfully", async () => {
      const task = insertTask("pending");

      const response = await request(app).delete(`/api/v1/suggested-tasks/${task.id}`);

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
      expect(response.body.data.archived).toBe(true);
    });

    it("should return 404 for non-existent task", async () => {
      const response = await request(app).delete("/api/v1/suggested-tasks/nonexistent-id");
      expect(response.status).toBe(404);
    });
  });

  describe("Scanner Confidence Scoring", () => {
    it("should assign higher confidence to critical keywords", async () => {
      const response = await request(app).post("/api/v1/suggested-tasks/scan");
      expect(response.status).toBe(200);

      const tasks = getArray(response.body.data, "tasks");
      tasks.forEach((task) => {
        const score = getNumber(task, "confidence_score");
        expect(typeof score).toBe("number");
        if (typeof score === "number") {
          expect(score).toBeGreaterThanOrEqual(0);
          expect(score).toBeLessThanOrEqual(1);
        }
      });

      const criticalTasks = tasks.filter((task) => {
        const text = getString(task, "todo_text");
        return text?.toLowerCase().includes("critical") ?? false;
      });

      if (criticalTasks.length > 0) {
        const score = getNumber(criticalTasks[0], "confidence_score");
        expect(score).toBeGreaterThan(0.5);
      }
    });
  });
});

import { logInfo, logError } from './logger.js';

export interface BrowserCommand {
    action: 'launch' | 'navigate' | 'click' | 'type' | 'screenshot' | 'content' | 'scroll' | 'wait' | 'extract' | 'close';
    url?: string;
    selector?: string;
    text?: string;
    headless?: boolean;
    // NEW: scroll parameters
    direction?: 'up' | 'down' | 'left' | 'right';
    amount?: number;
    // NEW: wait parameters
    timeout?: number;
    // NEW: extract parameters
    type?: 'text' | 'attribute' | 'html';
    attribute?: string;
}

export interface BrowserResponse {
    status: 'success' | 'error';
    message?: string;
    url?: string;
    screenshot?: string; // base64
    content?: string;
    data?: any; // NEW: for extract results
    count?: number; // NEW: number of extracted elements
}

export class PersistentBrowser {
    private process: any = null; // ChildProcess
    private lastScreenshot: Uint8Array | null = null;
    private pendingCommands: { resolve: (value: any) => void; reject: (reason?: any) => void }[] = [];
    private buffer: string = '';
    private startPromise: Promise<void> | null = null;

    constructor() {}

    private async getPythonPath(): Promise<string> {
        if (typeof process === 'undefined' || !process.versions?.node) return 'python';
        const fs = await import('fs');
        const venvPath = process.platform === 'win32' ? '.venv/Scripts/python.exe' : '.venv/bin/python';
        if (fs.existsSync(venvPath)) {
            return venvPath;
        }
        return 'python';
    }

    private async startProcess() {
        if (this.process) return;
        if (typeof process === 'undefined' || !process.versions?.node) {
             throw new Error("Browser agent only supported in Node.js environment");
        }

        const path = (await import('path')).default;
        const { spawn } = await import('child_process');

        const scriptPath = path.resolve(process.cwd(), 'myai/interactive_browser.py');
        const pythonExec = await this.getPythonPath();

        logInfo('PersistentBrowser', `Starting browser process: ${pythonExec} ${scriptPath}`);

        this.process = spawn(pythonExec, [scriptPath], {
            stdio: ['pipe', 'pipe', 'pipe']
        });

        this.process.stdout.on('data', (data: any) => {
            this.buffer += data.toString();

            let lines = this.buffer.split('\n');
            this.buffer = lines.pop() || ''; // Keep the last partial line

            for (const line of lines) {
                if (!line.trim()) continue;
                try {
                    const response = JSON.parse(line);
                    this.handleResponse(response);
                } catch (e) {
                    logError('PersistentBrowser', `Failed to parse response: ${line}`);
                }
            }
        });

        this.process.stderr.on('data', (data: any) => {
            logError('PersistentBrowser', `Python stderr: ${data.toString()}`);
        });

        this.process.on('close', (code: any) => {
            logInfo('PersistentBrowser', `Browser process exited with code ${code}`);
            this.process = null;
            // Reject all pending
            while (this.pendingCommands.length > 0) {
                const { reject } = this.pendingCommands.shift()!;
                reject(new Error('Browser process exited'));
            }
        });
    }

    private handleResponse(response: BrowserResponse) {
        if (this.pendingCommands.length > 0) {
            const { resolve, reject } = this.pendingCommands.shift()!;

            if (response.status === 'success') {
                if (response.screenshot) {
                    try {
                        this.lastScreenshot = Buffer.from(response.screenshot, 'base64');
                        // Remove base64 from object to keep it light
                        delete response.screenshot;
                    } catch (e) {
                        logError('PersistentBrowser', 'Failed to decode screenshot');
                    }
                }
                resolve(response);
            } else {
                reject(new Error(response.message || 'Unknown error'));
            }
        }
    }

    public async sendCommand(command: BrowserCommand): Promise<BrowserResponse> {
        if (!this.process) {
            if (!this.startPromise) {
                this.startPromise = this.startProcess();
            }
            try {
                await this.startPromise;
            } catch (e) {
                this.startPromise = null;
                throw new Error("Failed to start browser process: " + String(e));
            }
        }

        return new Promise((resolve, reject) => {
            this.pendingCommands.push({ resolve, reject });
            const jsonCmd = JSON.stringify(command) + '\n';
            if (this.process && this.process.stdin) {
                this.process.stdin.write(jsonCmd);
            } else {
                reject(new Error("Process failed to start or is not running"));
            }
        });
    }

    public getLastScreenshot(): Uint8Array | null {
        return this.lastScreenshot;
    }

    public async close() {
        if (this.process) {
            await this.sendCommand({ action: 'close' }).catch(() => {}); // Ignore error if already closed
            if (this.process) this.process.kill();
            this.process = null;
            this.lastScreenshot = null;
        }
    }
}

export const persistentBrowser = new PersistentBrowser();

import sys
import json
import asyncio
import base64
import os
from playwright.async_api import async_playwright

# Ensure we use unbuffered stdout for JSON communication
# sys.stdout.reconfigure(encoding='utf-8') # Python 3.7+

async def main():
    async with async_playwright() as p:
        browser = None
        context = None
        page = None

        async def get_page():
            nonlocal browser, context, page
            if not browser:
                # Default to headless unless specified otherwise in env or args
                headless = os.getenv("HEADLESS", "true").lower() == "true"
                browser = await p.chromium.launch(headless=headless, args=['--no-sandbox', '--disable-setuid-sandbox'])
                context = await browser.new_context(viewport={'width': 1280, 'height': 720})
                page = await context.new_page()
            return page

        loop = asyncio.get_running_loop()

        while True:
            try:
                line = await loop.run_in_executor(None, sys.stdin.readline)
                if not line:
                    break

                cmd = json.loads(line)
                action = cmd.get("action")
                result = {"status": "error", "message": "Unknown action"}

                if action == "launch":
                    await get_page() # Initializes browser
                    result = {"status": "success", "message": "Browser launched"}

                elif action == "navigate":
                    pg = await get_page()
                    url = cmd.get("url")
                    if url:
                        await pg.goto(url)
                        result = {"status": "success", "url": pg.url}
                    else:
                        result = {"status": "error", "message": "URL missing"}

                elif action == "click":
                    pg = await get_page()
                    selector = cmd.get("selector")
                    if selector:
                        try:
                            await pg.click(selector, timeout=5000)
                            result = {"status": "success", "message": f"Clicked {selector}"}
                        except Exception as e:
                            result = {"status": "error", "message": str(e)}
                    else:
                        result = {"status": "error", "message": "Selector missing"}

                elif action == "type":
                    pg = await get_page()
                    selector = cmd.get("selector")
                    text = cmd.get("text")
                    if selector and text is not None:
                        try:
                            await pg.fill(selector, text, timeout=5000)
                            result = {"status": "success", "message": f"Typed into {selector}"}
                        except Exception as e:
                            result = {"status": "error", "message": str(e)}
                    else:
                        result = {"status": "error", "message": "Selector or text missing"}

                elif action == "screenshot":
                    pg = await get_page()
                    try:
                        screenshot_bytes = await pg.screenshot(type='png')
                        b64 = base64.b64encode(screenshot_bytes).decode('utf-8')
                        result = {"status": "success", "screenshot": b64}
                    except Exception as e:
                        result = {"status": "error", "message": str(e)}

                elif action == "content":
                    pg = await get_page()
                    content = await pg.content()
                    result = {"status": "success", "content": content}

                # ==================== NEW ACTIONS (RobotkezV2) ====================

                elif action == "scroll":
                    pg = await get_page()
                    direction = cmd.get("direction", "down")
                    amount = cmd.get("amount", 100)

                    try:
                        if direction == "down":
                            await pg.evaluate(f"window.scrollBy(0, {amount})")
                        elif direction == "up":
                            await pg.evaluate(f"window.scrollBy(0, -{amount})")
                        elif direction == "left":
                            await pg.evaluate(f"window.scrollBy(-{amount}, 0)")
                        elif direction == "right":
                            await pg.evaluate(f"window.scrollBy({amount}, 0)")
                        else:
                            result = {"status": "error", "message": f"Invalid direction: {direction}"}
                            print(json.dumps(result), flush=True)
                            continue

                        result = {"status": "success", "message": f"Scrolled {direction} by {amount}px"}
                    except Exception as e:
                        result = {"status": "error", "message": str(e)}

                elif action == "wait":
                    pg = await get_page()
                    selector = cmd.get("selector")
                    timeout = cmd.get("timeout", 5000)

                    if selector:
                        try:
                            await pg.wait_for_selector(selector, timeout=timeout)
                            result = {"status": "success", "message": f"Element {selector} is visible"}
                        except Exception as e:
                            result = {"status": "error", "message": f"Timeout waiting for {selector}: {str(e)}"}
                    else:
                        result = {"status": "error", "message": "Selector missing"}

                elif action == "extract":
                    pg = await get_page()
                    selector = cmd.get("selector")
                    extract_type = cmd.get("type", "text")
                    attribute = cmd.get("attribute")

                    if not selector:
                        result = {"status": "error", "message": "Selector missing"}
                    else:
                        try:
                            elements = await pg.query_selector_all(selector)

                            if extract_type == "text":
                                data = []
                                for el in elements:
                                    text = await el.inner_text()
                                    data.append(text)

                            elif extract_type == "attribute":
                                if not attribute:
                                    result = {"status": "error", "message": "Attribute name missing"}
                                    print(json.dumps(result), flush=True)
                                    continue
                                data = []
                                for el in elements:
                                    attr_value = await el.get_attribute(attribute)
                                    data.append(attr_value)

                            elif extract_type == "html":
                                data = []
                                for el in elements:
                                    html = await el.inner_html()
                                    data.append(html)

                            else:
                                result = {"status": "error", "message": f"Invalid extract type: {extract_type}"}
                                print(json.dumps(result), flush=True)
                                continue

                            result = {"status": "success", "data": data, "count": len(data)}
                        except Exception as e:
                            result = {"status": "error", "message": str(e)}

                # ==================== END NEW ACTIONS ====================

                elif action == "close":
                    if browser:
                        await browser.close()
                        browser = None
                        page = None
                        context = None
                    result = {"status": "success", "message": "Browser closed"}

                print(json.dumps(result), flush=True)

            except json.JSONDecodeError:
                print(json.dumps({"status": "error", "message": "Invalid JSON"}), flush=True)
            except Exception as e:
                print(json.dumps({"status": "error", "message": str(e)}), flush=True)

if __name__ == "__main__":
    # Windows fix: Use ProactorEventLoop (default in Python 3.8+)
    # Playwright requires ProactorEventLoop on Windows
    if sys.platform == 'win32':
        # For Python 3.8+, ProactorEventLoop is default - no need to set
        # WindowsSelectorEventLoopPolicy causes issues with Playwright subprocess
        pass

    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass
